function normalizePhone(value) {
  const text = String(value ?? '').trim();
  if (!text || !/^\+?[\d\s().-]+$/.test(text)) return null;
  let digits = text.replace(/\D/g, '');
  if (digits.startsWith('001') && digits.length === 13) digits = digits.slice(3);
  else if (digits.startsWith('1') && digits.length === 11) digits = digits.slice(1);
  if (digits.length !== 10 || !/^[2-9]\d{2}[2-9]\d{6}$/.test(digits)) return null;
  return '+1' + digits;
}
function normalizeDob(value) {
  const text = String(value ?? '').trim();
  const match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (match) {
    const day = Number(match[1]), month = Number(match[2]), year = Number(match[3]);
    const dt = new Date(Date.UTC(year, month - 1, day));
    if (dt.getUTCFullYear() === year && dt.getUTCMonth() === month - 1 && dt.getUTCDate() === day) return `${year.toString().padStart(4,'0')}-${month.toString().padStart(2,'0')}-${day.toString().padStart(2,'0')}`;
    return null;
  }
  const serial = Number(value);
  if (!Number.isFinite(serial) || serial < 1 || serial > 100000) return null;
  return new Date(Date.UTC(1899, 11, 30) + Math.floor(serial) * 86400000).toISOString().slice(0, 10);
}
const secret = $env.RPT_N8N_INTAKE_SECRET;
if (!secret) throw new Error('Missing RPT_N8N_INTAKE_SECRET');
if (!globalThis.crypto?.subtle || !globalThis.crypto?.randomUUID) throw new Error('Web Crypto is unavailable');
const encoder = new TextEncoder();
const key = await globalThis.crypto.subtle.importKey('raw', encoder.encode(secret), {name:'HMAC',hash:'SHA-256'}, false, ['sign']);
const output = [];
for (const [index,item] of $input.all().entries()) {
  const row = item.json;
  const oldLeadId = String(row['Lead ID'] ?? '').trim();
  const sheetPhone = String(row['Phone Number'] ?? '').trim();
  const phone = normalizePhone(sheetPhone);
  const dob = normalizeDob(row['Date Of Birth']);
  const errors = [];
  if (!oldLeadId) errors.push('Lead ID is required');
  if (!phone) errors.push('invalid phone number');
  if (String(row['Date Of Birth'] ?? '').trim() && !dob) errors.push('Date Of Birth must be DD/MM/YYYY');
  const email = String(row.Email ?? '').trim().toLowerCase();
  if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errors.push('invalid email');
  const requestId = globalThis.crypto.randomUUID();
  const requestBody = {lead_id:oldLeadId,lead:{full_name:String(row.Name ?? '').trim() || null,phone,email:email || null,date_of_birth:dob,location:String(row.Location ?? '').trim() || null,title:String(row.Title ?? '').trim() || null}};
  const timestamp = Math.floor(Date.now()/1000).toString();
  const rawBody = JSON.stringify(requestBody);
  let signature = '';
  if (!errors.length) {
    const signed = await globalThis.crypto.subtle.sign('HMAC', key, encoder.encode(timestamp + '.' + rawBody));
    signature = 'sha256=' + Array.from(new Uint8Array(signed)).map(byte => byte.toString(16).padStart(2,'0')).join('');
  }
  output.push({json:{...row,oldLeadId,sheetPhone,requestId,valid:errors.length===0,validationError:errors.join('; '),requestBody,rawBody,timestamp,signature},pairedItem:{item:index}});
}
return output;

const sources = $('Build and Sign Profile Sync').all().filter(item => item.json.valid);
const byRequest = new Map(sources.map(item => [String(item.json.requestId), item.json]));
const output = [];
for (const [index,item] of $input.all().entries()) {
  const response = item.json;
  const status = Number(response.statusCode || 0);
  let body = response.body || {};
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
  const source = byRequest.get(String(body.request_id || '')) || sources[index]?.json;
  if (!source) throw new Error('Could not match AWS response to its Sheet row');
  const success = status === 200 || status === 201;
  const detail = typeof body.detail === 'string' ? body.detail : (body.code || response.error?.message || 'request rejected');
  output.push({json:{...source,httpStatus:status,result:body.result || '',failed:!success,errorText:'Error: ' + String(detail).slice(0,180)},pairedItem:{item:index}});
}
return output;
